  testWidgets('Study mixed folders preserve deep links and navigate recursive children', (tester) async {
    final year=fixtureTree.first;
    final semester=(year['semesters'] as List).first as Map;
    final subject=(semester['subjects'] as List).first as Map;
    final section=(subject['sections'] as List).first as Map;
    final topic=(section['topics'] as List).first as Map;
    topic['folders']=[{'id':'extra','title':'Extra folder','files':[
      {'id':'extra-file','title':'Reference PDF','pdfUrl':'https://example.org/reference.pdf','published':true},
    ]}];
    await open(tester,'/study/notes/id-0/id-1/id-2/id-3/id-4');
    expect(find.text('Insulin Notes'),findsOneWidget);
    expect(find.text('Extra folder'),findsOneWidget);
    await tester.tap(find.text('Extra folder')); await tester.pumpAndSettle();
    expect(find.text('Reference PDF'),findsOneWidget);
    expect(GoRouterState.of(tester.element(find.text('Reference PDF'))).uri.queryParametersAll['folder'],['extra']);
    expect(find.text('Load preview'),findsOneWidget);
  });
  if (const bool.fromEnvironment('HYZEN_CAPTURE_QA')) {
    testWidgets('representative screens visual QA', (tester) async {
      tester.view.physicalSize = const Size(390, 844);
      tester.view.devicePixelRatio = 1;
      addTearDown(tester.view.resetPhysicalSize);
      addTearDown(tester.view.resetDevicePixelRatio);
      for (final mode in [ThemeMode.dark, ThemeMode.light]) {
        await tester.pumpWidget(const SizedBox.shrink());
        await tester.pumpAndSettle();
        container.read(themeModeProvider.notifier).set(mode);
        for (final path in [
          '/home',
          '/study',
          '/pdf-studio',
          '/study/notes/id-0/id-1/id-2/id-3/id-4',
          '/downloads',
          '/profile',
          '/profile/edit',
          '/contact',
          '/settings',
          '/about',
        ]) {
          await open(tester, path);
          await tester.runAsync(
            () => Future<void>.delayed(const Duration(milliseconds: 60)),
          );
          await tester.pump(const Duration(milliseconds: 500));
          await tester.runAsync(
            () => Future<void>.delayed(const Duration(milliseconds: 120)),
          );
          await tester.pump();
          await expectLater(
            find.byType(HyzenApp),
            matchesGoldenFile(
              '../qa/${mode.name}${path.replaceAll('/', '_')}.png',
            ),
          );
          expect(tester.takeException(), isNull);
        }
      }
    });
  }
}

