import 'package:hyzen_pharmd/features/downloads/presentation/transfer_status.dart';

DownloadRecord record(DownloadStatus status, {int bytes = 0, int? total, double legacy = .8, String? path}) => DownloadRecord(
  key: 'fixture', kind: LibraryKind.notes, title: 'Notes', sourceUrl: 'https://example.org/notes.pdf',
  status: status, sizeBytes: bytes, totalBytes: total, progress: legacy, localPath: path,
);

void main() {
  setUpAll(() async {
    final font = FontLoader('Manrope');
    font.addFont(rootBundle.load('assets/fonts/Manrope-400.ttf'));
    await font.load();
  });
  test('Progress requires a measured total, distinguishes zero and clamps bytes', () {
    expect(measuredDownloadProgress(record(DownloadStatus.downloading, bytes: 80)), isNull);
    expect(downloadStatusLabel(record(DownloadStatus.downloading, bytes: 80)), isNot(contains('%')));
    expect(measuredDownloadProgress(record(DownloadStatus.downloading, total: 100)), 0);
    expect(measuredDownloadProgress(record(DownloadStatus.downloading, bytes: 25, total: 100)), .25);
    expect(measuredDownloadProgress(record(DownloadStatus.downloading, bytes: 200, total: 100)), 1);
    expect(downloadStatusLabel(record(DownloadStatus.failed)), contains('retry'));
    expect(downloadStatusLabel(record(DownloadStatus.ready)), isNot(contains('Downloaded')));
    expect(downloadStatusLabel(record(DownloadStatus.ready, path: '/private/offline.pdf')), contains('Downloaded'));
  });
  testWidgets('Reduced motion status switches immediately without invented completion', (tester) async {
    Widget app(DownloadRecord r) => MaterialApp(home: MediaQuery(data: const MediaQueryData(disableAnimations: true),
      child: Scaffold(body: TransferStatus(record: r))));
    await tester.pumpWidget(app(record(DownloadStatus.downloading, total: 100)));
    expect(tester.widget<LinearProgressIndicator>(find.byType(LinearProgressIndicator)).value, 0);
    await tester.pumpWidget(app(record(DownloadStatus.failed)));
    await tester.pumpAndSettle();
    expect(find.text('Interrupted · tap to retry'), findsOneWidget);
    expect(find.byType(LinearProgressIndicator), findsNothing);
    expect(tester.binding.hasScheduledFrame, isFalse);
    expect(tester.takeException(), isNull);
  });
  testWidgets('Icon family renders at 16/24/32 in light and dark', (tester) async {
    tester.view.physicalSize = const Size(400, 720);
    tester.view.devicePixelRatio = 1;
    addTearDown(tester.view.resetPhysicalSize);
    addTearDown(tester.view.resetDevicePixelRatio);
    for (final brightness in Brightness.values) {
      await tester.pumpWidget(MaterialApp(debugShowCheckedModeBanner: false, theme: ThemeData(brightness: brightness, fontFamily: 'Manrope'), home: Scaffold(body: GridView.count(
        crossAxisCount: 4, childAspectRatio: 1.2, padding: const EdgeInsets.all(8), children: [
          for (final kind in HyzenSymbolKind.values)
            Column(mainAxisAlignment: MainAxisAlignment.center, children: [
              Row(mainAxisAlignment: MainAxisAlignment.center, crossAxisAlignment: CrossAxisAlignment.center, children: [
                for (final size in [16.0, 24.0, 32.0])
                  HyzenSymbol(kind, size: size, color: brightness == Brightness.light ? Colors.black : Colors.white),
              ]),
              Text(kind.name, style: const TextStyle(fontSize: 10)),
            ]),
        ],
      ))));
      await tester.pumpAndSettle();
      expect(tester.takeException(), isNull);
      if (const bool.fromEnvironment('HYZEN_CAPTURE_QA')) {
        await expectLater(find.byType(MaterialApp), matchesGoldenFile('../qa/symbols_${brightness.name}.png'));
      }
    }
  });
}

