                    crossAxisCount: constraints.crossAxisExtent < 280 || MediaQuery.textScalerOf(context).scale(1) > 1.6 ? 1 : 2,
                    mainAxisExtent: MediaQuery.textScalerOf(context).scale(1) > 1.6 ? 400 : 312,
                    crossAxisSpacing: 12, mainAxisSpacing: 12),
                  itemCount: visibleFiles.length, itemBuilder: (context,i) {
                    final file = visibleFiles[i];
