            Text(snapshot.hasError ? 'Preview unavailable' : 'First-page preview', style: theme.textTheme.bodySmall, textAlign: TextAlign.center),
            TextButton(onPressed: () => _load(path), child: Text(snapshot.hasError ? 'Retry preview' : 'Load preview')),
          ]);
        })),
