        Expanded(child: Text(widget.file.title, maxLines: 3, overflow: TextOverflow.ellipsis, style: theme.textTheme.titleSmall)),
        Text(record?.isReady == true ? 'Saved offline' : record?.status == DownloadStatus.downloading ? 'Downloading…' : 'Study file', style: theme.textTheme.labelSmall),
        const SizedBox(height: 4),
