import '../domain/drive.dart';

class _LimitedClient extends http.BaseClient {
  _LimitedClient(this.inner);
  final http.Client inner;
  static const limit = 16 * 1024 * 1024;
  @override
  Future<http.StreamedResponse> send(http.BaseRequest request) async {
    final response = await inner.send(request);
    if ((response.contentLength ?? 0) > limit) { inner.close(); throw FriendlyException('Preview is too large. Open the original file.'); }
    Stream<List<int>> bounded() async* {
      var count = 0;
      await for (final chunk in response.stream) {
        count += chunk.length;
        if (count > limit) { inner.close(); throw FriendlyException('Preview is too large. Open the original file.'); }
        yield chunk;
      }
    }
    return http.StreamedResponse(bounded(), response.statusCode, headers: response.headers,
      contentLength: response.contentLength, request: response.request, reasonPhrase: response.reasonPhrase);
  }
  @override
  void close() => inner.close();
}

/// Separate disposable preview cache. Never writes download metadata or originals.
class StudyPreviewRepository {
  StudyPreviewRepository({this.directory, this.clientFactory, this.render});
  static final instance = StudyPreviewRepository();
  final Directory? directory;
  final http.Client Function()? clientFactory;
  final Future<Uint8List> Function(String path)? render;
  final _pending = <String, Future<Uint8List>>{};
  final _memory = LinkedHashMap<String, ({Uint8List bytes, DateTime loaded})>();
  Future<void> _tail = Future.value();

  Future<void> clear() {
    final task = _tail.then((_) async {
      _memory.clear();
      final base = directory ?? Directory('${(await getTemporaryDirectory()).path}/study_previews_v1');
      if (!await base.exists()) return;
      await for (final entry in base.list()) {
        if (entry is File && (entry.path.endsWith('.png') || entry.path.endsWith('.png.identity') || entry.path.endsWith('.png.part'))) {
          await entry.delete();
        }
      }
    });
    _tail = task.then<void>((_) {}, onError: (Object _, StackTrace __) {});
    return task;
  }

  Future<Uint8List> load(String url, {String? localPath, String? version}) async {
    final stamp = localPath == null ? '' : '${(await File(localPath).stat()).modified.millisecondsSinceEpoch}';
    final key = jsonEncode([url, version, localPath, stamp]);
    // Keep filenames bounded even for long private paths/URLs.
    var hash = 2166136261;
    for (final unit in key.codeUnits) { hash = ((hash ^ unit) * 16777619) & 0xffffffff; }
    final id = '${DriveLinks.offlineKey(url)}_${hash.toRadixString(16)}'.replaceAll(RegExp(r'[^A-Za-z0-9_-]'), '_');
    final hit = _memory.remove(key);
    if (hit != null && DateTime.now().difference(hit.loaded) < const Duration(hours: 6)) { _memory[key] = hit; return hit.bytes; }
    final pending = _pending[key]; if (pending != null) return pending;
    final task = _tail.then((_) => _load(id, key, url, localPath));
    _tail = task.then<void>((_) {}, onError: (Object _, StackTrace __) {});
    _pending[key] = task;
    unawaited(task.then<void>((_) { _pending.remove(key); }, onError: (Object _, StackTrace __) { _pending.remove(key); }));
    return task;
  }

  Future<Uint8List> _load(String id, String identity, String url, String? localPath) async {
    final base = directory ?? Directory('${(await getTemporaryDirectory()).path}/study_previews_v1');
    await base.create(recursive: true);
    final cache = File('${base.path}/$id.png');
    final identityFile = File('${cache.path}.identity');
    if (await cache.exists()) {
      final stat = await cache.stat();
      String? storedIdentity;
      try { if (await identityFile.exists()) storedIdentity = await identityFile.readAsString(); } catch (_) {}
      if (storedIdentity == identity && DateTime.now().difference(stat.modified) < const Duration(hours: 6) && stat.size < 6 * 1024 * 1024) {
        try {
          final bytes = await cache.readAsBytes();
          final codec = await ui.instantiateImageCodec(bytes, targetWidth: 320, allowUpscaling: false);
          try { final frame = await codec.getNextFrame(); frame.image.dispose(); } finally { codec.dispose(); }
          _remember(identity, bytes); return bytes;
        } catch (_) { /* Corrupt disposable cache: regenerate from source. */ }
      }
      await cache.delete();
    }
    final store = createFileStore(testDirectory: base,
      clientFactory: () => _LimitedClient(clientFactory?.call() ?? http.Client()));
    String? temporary;
    try {
      final path = localPath ?? (temporary = (await store.download(url, id, (_, __) {})).path);
      final handle = await File(path).open();
      final head = await handle.read(5); await handle.close();
      if (!PdfSniffer.isPdf(head)) throw FriendlyException('First-page preview is available for PDFs. Open this file to read it.');
      final Uint8List image;
      if (render != null) { image = await render!(path); }
      else {
        final page = await StudioPdfEngine.renderPage(path, 0, maxEdge: 320);
        final codec = await ui.instantiateImageCodec(page.bytes, targetWidth: 320, allowUpscaling: false);
        final frame = await codec.getNextFrame();
        try {
          final encoded = await frame.image.toByteData(format: ui.ImageByteFormat.png);
          if (encoded == null) throw StateError('Preview unavailable');
          image = encoded.buffer.asUint8List();
        } finally { frame.image.dispose(); codec.dispose(); }
      }
      final partial = File('${cache.path}.part');
      await partial.writeAsBytes(image, flush: true);
      await partial.rename(cache.path);
      await identityFile.writeAsString(identity, flush: true);
      _remember(identity, image);
      await _trim(base);
      return image;
    } finally {
      if (temporary != null) await store.delete(temporary);
      await store.discardPartial(id);
    }
  }
  void _remember(String id, Uint8List bytes) {
    _memory[id] = (bytes: bytes, loaded: DateTime.now());
    while (_memory.length > 24 || _memory.values.fold<int>(0, (n,b) => n+b.bytes.length) > 6*1024*1024) {
      _memory.remove(_memory.keys.first);
    }
  }
  Future<void> _trim(Directory base) async {
    final files = await base.list().where((e) => e is File && e.path.endsWith('.png')).cast<File>().toList();
    final entries = <(File,FileStat)>[];
    for (final f in files) { entries.add((f,await f.stat())); }
    entries.sort((a,b) => a.$2.modified.compareTo(b.$2.modified));
    var total = entries.fold<int>(0,(n,e) => n+e.$2.size);
    for (final entry in entries) {
      if (total <= 12*1024*1024) break;
      total -= entry.$2.size; await entry.$1.delete();
      final identity = File('${entry.$1.path}.identity');
      if (await identity.exists()) await identity.delete();
    }
  }
}

