StudyTree _parse(Map<String,dynamic> input) => StudyTree.parse(LibraryKind.values.byName(input['kind']), input['value']);
final parsedStudyTreeProvider = FutureProvider.family<Loaded<StudyTree>, LibraryKind>((ref, kind) async {
  final source = await ref.watch(contentProvider(kind.storageKey).future);
  final tree = await compute(_parse, {'kind': kind.name, 'value': source.value});
  return Loaded(tree, fromCache: source.fromCache, fetchedAt: source.fetchedAt);
});
final studyTreeProvider = Provider.family<AsyncValue<Loaded<StudyTree>>, LibraryKind>((ref, kind) {
  final year = ref.watch(professionalYearProvider);
  final admin = ref.watch(isAdminProvider);
  return ref.watch(parsedStudyTreeProvider(kind)).whenData((loaded) => Loaded(
    loaded.data.forYear(year, admin: admin), fromCache: loaded.fromCache, fetchedAt: loaded.fetchedAt));
});

