import 'download_record.dart';
import '../../academics/domain/models.dart';

enum SavedView { all, saved, progress, failed }
bool matchesSavedView(DownloadRecord r, SavedView view) => switch (view) {
  SavedView.all => true,
  SavedView.saved => r.isReady,
  SavedView.progress => r.status == DownloadStatus.downloading || r.status == DownloadStatus.paused,
  SavedView.failed => r.status == DownloadStatus.failed || (r.status == DownloadStatus.ready && !r.isReady),
};
List<String> savedTrail(DownloadRecord r) => [r.kind.shortTitle, ...r.trail.where((p) => p.trim().isNotEmpty)];

class DownloadListing {
  const DownloadListing(this.folders, this.files);
  final Map<String,int> folders;
  final List<DownloadRecord> files;
}
/// Virtual hierarchy over existing metadata; no physical move or key migration.
DownloadListing browseDownloads(Iterable<DownloadRecord> records, List<String> path, {bool grouped = true}) {
  if (!grouped) return DownloadListing(const {}, records.toList());
  final folders = <String,int>{}; final files = <DownloadRecord>[];
  for (final record in records) {
    final trail = savedTrail(record);
    if (path.length > trail.length) continue;
    var matches = true;
    for (var i=0; i<path.length; i++) { if (trail[i] != path[i]) { matches = false; break; } }
    if (!matches) continue;
    if (trail.length == path.length) { files.add(record); }
    else { final next = trail[path.length]; folders[next] = (folders[next] ?? 0) + 1; }
  }
  return DownloadListing(folders, files);
}

