package com.hyzen.pharmd

import android.graphics.BitmapFactory
import android.graphics.Color
import android.graphics.Paint
import android.graphics.pdf.PdfDocument
import androidx.test.ext.junit.runners.AndroidJUnit4
import androidx.test.platform.app.InstrumentationRegistry
import org.junit.Assert.*
import org.junit.Test
import org.junit.runner.RunWith
import java.io.File

@RunWith(AndroidJUnit4::class)
class StudyPreviewRendererTest {
    private fun source(): File {
        val context = InstrumentationRegistry.getInstrumentation().targetContext
        val file = File.createTempFile("study_preview_", ".pdf", context.cacheDir)
        val document = PdfDocument()
        try {
            listOf(Color.RED, Color.BLUE).forEachIndexed { index, color ->
                val page = document.startPage(PdfDocument.PageInfo.Builder(300, 420, index + 1).create())
                page.canvas.drawRect(0f, 0f, 300f, 420f, Paint().apply { this.color = color })
                document.finishPage(page)
            }
            file.outputStream().use { document.writeTo(it) }
        } finally { document.close() }
        return file
    }
    @Test fun actualPagePixelsAreBoundedAndOriginalRemainsIdentical() {
        val original = source()
        try {
            val before = original.readBytes()
            for ((index, color) in listOf(Color.RED, Color.BLUE).withIndex()) {
                val result = PdfPagePreviewRenderer.render(original.path, index, 320)
                val bytes = result["bytes"] as ByteArray
                val image = BitmapFactory.decodeByteArray(bytes, 0, bytes.size)
                try {
                    assertTrue(image.width in 1..320)
                    assertTrue(image.height in 1..320)
                    assertEquals(color, image.getPixel(image.width / 2, image.height / 2))
                } finally { image.recycle() }
            }
            assertArrayEquals(before, original.readBytes())
        } finally { original.delete() }
    }
    @Test fun invalidPageFailsAndSubsequentValidRenderStillWorks() {
        val original = source()
        try {
            var rejected = false
            try { PdfPagePreviewRenderer.render(original.path, 2, 320) }
            catch (_: IllegalArgumentException) { rejected = true }
            assertTrue(rejected)
            assertTrue((PdfPagePreviewRenderer.render(original.path, 0)["width"] as Int) > 0)
        } finally { original.delete() }
    }
}
